import java.nio.file.*;import java.util.*;public class Driver {public static void main(String[]a)throws Exception{Path p=Path.of("app.log");Files.writeString(p,"INFO System started\nERROR Database timeout\nINFO Retrying connection\n");List<String> lines=Files.readAllLines(p);System.out.println("File: "+p.getFileName()+" | Size: "+Files.size(p)+" bytes");System.out.println("Total Lines: "+lines.size()+" | Matches for 'ERROR': "+lines.stream().filter(x->x.contains("ERROR")).count());Files.deleteIfExists(p);}}
